namespace ghidra.graph.support;



using ghidra.graph.graphs;
using ghidra.graph.viewer.layout;

/**
 * A visual graph implementation used for testing.
 */
public class TestVisualGraph : DefaultVisualGraph<AbstractTestVertex, TestEdge> {

	private VisualGraphLayout<AbstractTestVertex, TestEdge> layout;

	/* @Override */
	public VisualGraphLayout<AbstractTestVertex, TestEdge> getLayout() {
		return layout;
	}

	public void setLayout(VisualGraphLayout<AbstractTestVertex, TestEdge> layout) {
		this.layout = layout;
	}

	/* @Override */
	public DefaultVisualGraph<AbstractTestVertex, TestEdge> copy() {

		TestVisualGraph newGraph = new TestVisualGraph();

		Collection<AbstractTestVertex> myVertices = getVertices();
		foreach (AbstractTestVertex v in myVertices) {
			newGraph.addVertex(v);
		}

		Collection<TestEdge> myEdges = getEdges();
		foreach (TestEdge e in myEdges) {
			newGraph.addEdge(e);
		}

		newGraph.setLayout(layout);

		return newGraph;
	}
}
